-- STAGING ONLY: fictional booking-change test data (Phase 1). Run in the TiDB Cloud SQL editor on the STAGING cluster.
-- Every write below only happens when the current database is leadflow_staging (otherwise it changes 0 rows).
-- Creates 4 fictional customers (555-01xx numbers, example.com emails), their native bookings and visits, and one SMS
-- customer task each (2 with a Claude-style proposal, 2 for "Set up booking change"). No payment rows; nothing is sent.
-- Safe to run again: it first removes the previous test rows (see 02-remove.sql for the same removal on its own).

USE leadflow_staging;
SELECT DATABASE() AS must_be_leadflow_staging;

-- 1. Remove earlier test rows (only rows carrying the test markers)
DELETE FROM ops_chat_messages WHERE DATABASE() = 'leadflow_staging' AND activeDedupKey IN (SELECT k FROM (SELECT CONCAT('claude-booking-action:v1:', id) AS k FROM ops_chat_messages WHERE activeDedupKey LIKE 'staging-test-task:%') AS t);
DELETE FROM ops_chat_messages WHERE DATABASE() = 'leadflow_staging' AND activeDedupKey LIKE 'staging-test-task:%';
DELETE FROM leadflow_jobs WHERE DATABASE() = 'leadflow_staging' AND bookingId IN (SELECT id FROM (SELECT id FROM bookings WHERE publicBookingNumber LIKE 'STG-TEST-%') AS t);
DELETE FROM booking_series WHERE DATABASE() = 'leadflow_staging' AND bookingId IN (SELECT id FROM (SELECT id FROM bookings WHERE publicBookingNumber LIKE 'STG-TEST-%') AS t);
DELETE FROM bookings WHERE DATABASE() = 'leadflow_staging' AND publicBookingNumber LIKE 'STG-TEST-%';
DELETE FROM conversation_sessions WHERE DATABASE() = 'leadflow_staging' AND leadName LIKE '% (Staging Test)' AND leadPhone IN ('+12025550101', '+12025550102', '+12025550103', '+12025550104');

-- 2. Fictional conversations (the customer's SMS)
INSERT INTO conversation_sessions (leadPhone, leadName, messageHistory) SELECT '+12025550101', 'Alice (Staging Test)', JSON_ARRAY(JSON_OBJECT('role', 'user', 'content', 'Hi! Something came up. Could we move my cleaning three days later, at 2pm?', 'ts', UNIX_TIMESTAMP() * 1000)) FROM DUAL WHERE DATABASE() = 'leadflow_staging';
INSERT INTO conversation_sessions (leadPhone, leadName, messageHistory) SELECT '+12025550102', 'Ben (Staging Test)', JSON_ARRAY(JSON_OBJECT('role', 'user', 'content', 'Hi, please cancel my cleaning. Sorry for the trouble!', 'ts', UNIX_TIMESTAMP() * 1000)) FROM DUAL WHERE DATABASE() = 'leadflow_staging';
INSERT INTO conversation_sessions (leadPhone, leadName, messageHistory) SELECT '+12025550103', 'Carla (Staging Test)', JSON_ARRAY(JSON_OBJECT('role', 'user', 'content', 'Hi, could you move next week''s cleaning (the second one) two days later? Same time is fine.', 'ts', UNIX_TIMESTAMP() * 1000)) FROM DUAL WHERE DATABASE() = 'leadflow_staging';
INSERT INTO conversation_sessions (leadPhone, leadName, messageHistory) SELECT '+12025550104', 'Dana (Staging Test)', JSON_ARRAY(JSON_OBJECT('role', 'user', 'content', 'Hello! Could you come two days later instead? Same morning window is fine.', 'ts', UNIX_TIMESTAMP() * 1000)) FROM DUAL WHERE DATABASE() = 'leadflow_staging';

-- 3. Native bookings (no payment taken: paymentStatus not_started)
