-- 4. Their scheduled visits (team assigned for display only)
INSERT INTO leadflow_jobs (origin, bookingId, jobDate, serviceDateTime, customerName, customerPhone, customerEmail, jobAddress, serviceName, bedrooms, bathrooms, extras, frequency, bookingStatus, teamName, jobTotalCents) SELECT 'native_booking', id, DATE_FORMAT(CURDATE() + INTERVAL 5 DAY, '%Y-%m-%d'), DATE_FORMAT(CONVERT_TZ(CONCAT(DATE_FORMAT(CURDATE() + INTERVAL 5 DAY, '%Y-%m-%d'), ' 10:00:00'), 'America/New_York', '+00:00'), '%Y-%m-%dT%H:%i:%s.000Z'), customerName, customerPhone, customerEmail, address, serviceName, bedrooms, bathrooms, '[]', 'One time', 'assigned', 'Staging Test Team', firstCleaningTotalCents FROM bookings WHERE DATABASE() = 'leadflow_staging' AND publicBookingNumber = 'STG-TEST-A';
INSERT INTO leadflow_jobs (origin, bookingId, jobDate, serviceDateTime, customerName, customerPhone, customerEmail, jobAddress, serviceName, bedrooms, bathrooms, extras, frequency, bookingStatus, teamName, jobTotalCents) SELECT 'native_booking', id, DATE_FORMAT(CURDATE() + INTERVAL 6 DAY, '%Y-%m-%d'), DATE_FORMAT(CONVERT_TZ(CONCAT(DATE_FORMAT(CURDATE() + INTERVAL 6 DAY, '%Y-%m-%d'), ' 11:00:00'), 'America/New_York', '+00:00'), '%Y-%m-%dT%H:%i:%s.000Z'), customerName, customerPhone, customerEmail, address, serviceName, bedrooms, bathrooms, '[]', 'One time', 'assigned', 'Staging Test Team', firstCleaningTotalCents FROM bookings WHERE DATABASE() = 'leadflow_staging' AND publicBookingNumber = 'STG-TEST-B';
INSERT INTO leadflow_jobs (origin, bookingId, jobDate, serviceDateTime, customerName, customerPhone, customerEmail, jobAddress, serviceName, bedrooms, bathrooms, extras, frequency, bookingStatus, teamName, jobTotalCents) SELECT 'native_booking', id, DATE_FORMAT(CURDATE() + INTERVAL 3 DAY, '%Y-%m-%d'), DATE_FORMAT(CONVERT_TZ(CONCAT(DATE_FORMAT(CURDATE() + INTERVAL 3 DAY, '%Y-%m-%d'), ' 09:00:00'), 'America/New_York', '+00:00'), '%Y-%m-%dT%H:%i:%s.000Z'), customerName, customerPhone, customerEmail, address, serviceName, bedrooms, bathrooms, '[]', 'Weekly', 'assigned', 'Staging Test Team', firstCleaningTotalCents FROM bookings WHERE DATABASE() = 'leadflow_staging' AND publicBookingNumber = 'STG-TEST-C';
INSERT INTO leadflow_jobs (origin, bookingId, jobDate, serviceDateTime, customerName, customerPhone, customerEmail, jobAddress, serviceName, bedrooms, bathrooms, extras, frequency, bookingStatus, teamName, jobTotalCents) SELECT 'native_booking', id, DATE_FORMAT(CURDATE() + INTERVAL 10 DAY, '%Y-%m-%d'), DATE_FORMAT(CONVERT_TZ(CONCAT(DATE_FORMAT(CURDATE() + INTERVAL 10 DAY, '%Y-%m-%d'), ' 09:00:00'), 'America/New_York', '+00:00'), '%Y-%m-%dT%H:%i:%s.000Z'), customerName, customerPhone, customerEmail, address, serviceName, bedrooms, bathrooms, '[]', 'Weekly', 'assigned', 'Staging Test Team', COALESCE(futureVisitTotalCents, firstCleaningTotalCents) FROM bookings WHERE DATABASE() = 'leadflow_staging' AND publicBookingNumber = 'STG-TEST-C';
INSERT INTO leadflow_jobs (origin, bookingId, jobDate, serviceDateTime, customerName, customerPhone, customerEmail, jobAddress, serviceName, bedrooms, bathrooms, extras, frequency, bookingStatus, teamName, jobTotalCents) SELECT 'native_booking', id, DATE_FORMAT(CURDATE() + INTERVAL 8 DAY, '%Y-%m-%d'), DATE_FORMAT(CONVERT_TZ(CONCAT(DATE_FORMAT(CURDATE() + INTERVAL 8 DAY, '%Y-%m-%d'), ' 08:00:00'), 'America/New_York', '+00:00'), '%Y-%m-%dT%H:%i:%s.000Z'), customerName, customerPhone, customerEmail, address, serviceName, bedrooms, bathrooms, '[]', 'One time', 'assigned', 'Staging Test Team', firstCleaningTotalCents FROM bookings WHERE DATABASE() = 'leadflow_staging' AND publicBookingNumber = 'STG-TEST-D';

-- 5. SMS customer tasks: created hidden, then completed in one update (the task list never sees a partial task)
INSERT INTO ops_chat_messages (channel, authorName, authorRole, body, quickAction, sessionId, cardStatus, activeDedupKey, lastActivityAt) SELECT NULL, 'Instinct', 'system', 'Reschedule cleaning', NULL, id, 'active', 'staging-test-task:A', UNIX_TIMESTAMP() * 1000 FROM conversation_sessions WHERE DATABASE() = 'leadflow_staging' AND leadPhone = '+12025550101' AND leadName = 'Alice (Staging Test)' ORDER BY id DESC LIMIT 1;
UPDATE ops_chat_messages SET channel = 'command', quickAction = 'claude_customer_task', metadata = JSON_OBJECT('taskId', id, 'task', JSON_OBJECT(
  'id', id, 'version', 1, 'kind', 'claude_customer_task', 'sessionId', sessionId, 'customerName', 'Alice (Staging Test)', 'customerPhone', '+12025550101',
  'sourceMessageId', 'staging-test-message-A', 'sourceText', 'Hi! Something came up. Could we move my cleaning three days later, at 2pm?', 'receivedAt', UNIX_TIMESTAMP() * 1000,
  'receivingPhoneNumberId', 'PN-staging-test', 'receivingPhoneNumber', '+12025550100', 'title', 'Reschedule cleaning',
  'items', JSON_ARRAY(JSON_OBJECT('id', 'item-1', 'title', 'Move the cleaning three days later at 2pm', 'evidenceQuote', 'move my cleaning three days later, at 2pm', 'completedBy', NULL, 'completedAt', NULL)),
  'status', 'unclaimed', 'owner', NULL, 'claimedAt', NULL, 'completedAt', NULL, 'completedBy', NULL, 'completionNote', NULL,
  'reply', JSON_OBJECT('text', 'Thanks! We''ll take care of it and confirm once it''s done.', 'status', 'sent', 'providerMessageId', 'staging-test-reply-A'),
  'activity', JSON_ARRAY(JSON_OBJECT('action', 'created', 'actor', NULL, 'at', UNIX_TIMESTAMP() * 1000, 'note', NULL))))
WHERE DATABASE() = 'leadflow_staging' AND activeDedupKey = 'staging-test-task:A';
