-- 6. Claude-style proposals for Alice (reschedule, exact time) and Carla (reschedule the second recurring visit)
INSERT INTO ops_chat_messages (channel, authorName, authorRole, body, quickAction, cardStatus, activeDedupKey, lastActivityAt, metadata)
SELECT 'instinct_booking_action', 'Instinct', 'system', 'Booking change proposal', 'claude_booking_action', 'active', CONCAT('claude-booking-action:v1:', id), UNIX_TIMESTAMP() * 1000,
  JSON_OBJECT('version', 1, 'taskId', id, 'source', 'claude', 'itemId', 'item-1',
    'request', JSON_OBJECT('type', 'reschedule_visit', 'visitDate', DATE_FORMAT(CURDATE() + INTERVAL 5 DAY, '%Y-%m-%d'), 'jobId', NULL, 'newDate', DATE_FORMAT(CURDATE() + INTERVAL 8 DAY, '%Y-%m-%d'), 'newTime', '14:00', 'evidenceQuote', 'move my cleaning three days later, at 2pm'),
    'revision', 1, 'status', 'proposed', 'execution', NULL, 'verification', NULL, 'confirmation', NULL,
    'history', JSON_ARRAY(JSON_OBJECT('action', 'proposed', 'actor', NULL, 'at', UNIX_TIMESTAMP() * 1000, 'note', 'Proposed by Claude (staging test data)')))
FROM ops_chat_messages WHERE DATABASE() = 'leadflow_staging' AND activeDedupKey = 'staging-test-task:A';
INSERT INTO ops_chat_messages (channel, authorName, authorRole, body, quickAction, cardStatus, activeDedupKey, lastActivityAt, metadata)
SELECT 'instinct_booking_action', 'Instinct', 'system', 'Booking change proposal', 'claude_booking_action', 'active', CONCAT('claude-booking-action:v1:', id), UNIX_TIMESTAMP() * 1000,
  JSON_OBJECT('version', 1, 'taskId', id, 'source', 'claude', 'itemId', 'item-1',
    'request', JSON_OBJECT('type', 'reschedule_visit', 'visitDate', DATE_FORMAT(CURDATE() + INTERVAL 10 DAY, '%Y-%m-%d'), 'jobId', NULL, 'newDate', DATE_FORMAT(CURDATE() + INTERVAL 12 DAY, '%Y-%m-%d'), 'newTime', NULL, 'evidenceQuote', 'move next week''s cleaning (the second one) two days later'),
    'revision', 1, 'status', 'proposed', 'execution', NULL, 'verification', NULL, 'confirmation', NULL,
    'history', JSON_ARRAY(JSON_OBJECT('action', 'proposed', 'actor', NULL, 'at', UNIX_TIMESTAMP() * 1000, 'note', 'Proposed by Claude (staging test data)')))
FROM ops_chat_messages WHERE DATABASE() = 'leadflow_staging' AND activeDedupKey = 'staging-test-task:C';

-- 7. Check: expect 4 bookings, 5 visits, 4 tasks, 2 proposals
SELECT (SELECT COUNT(*) FROM bookings WHERE publicBookingNumber LIKE 'STG-TEST-%') AS bookings,
  (SELECT COUNT(*) FROM leadflow_jobs WHERE bookingId IN (SELECT id FROM bookings WHERE publicBookingNumber LIKE 'STG-TEST-%')) AS visits,
  (SELECT COUNT(*) FROM ops_chat_messages WHERE activeDedupKey LIKE 'staging-test-task:%' AND quickAction = 'claude_customer_task') AS tasks,
  (SELECT COUNT(*) FROM ops_chat_messages WHERE activeDedupKey IN (SELECT CONCAT('claude-booking-action:v1:', id) FROM ops_chat_messages WHERE activeDedupKey LIKE 'staging-test-task:%')) AS proposals;
